6	 * @test @b insert_extract_sve
7	 * @parblock
8	 * SVE port of insert_extract: random lane insert + extract round-trip on
9	 * an SVE vector. Insert = predicate-gated single-lane write (svsel with a
10	 * single-lane predicate); extract = svlastb on the shifted vector or a
11	 * predicate-gated read. Store/load consistency via svst1/svld1 + svcmpeq.
12	 * @endparblock
13	 */
14	
15	#include <sandstone.h>
16	#include <cstdint>
17	#include <cstdio>
18	#include <random>
19	#include <cstring>
20	#include <atomic>
21	
22	#ifdef __aarch64__
23	#include <arm_sve.h>
24	#include <sys/auxv.h>
25	
26	#ifndef HWCAP_SVE
27	#define HWCAP_SVE (1 << 22)
28	#endif
29	#endif
30	
31	#define IE_LANES 4
32	
33	struct test_data_sve {
34	    float mem_buf[16];
35	};
36	
37	static int insert_extract_sve_init(struct test *test) {
38	    (void)test;
39	#ifdef __aarch64__
40	    unsigned long hwcap = getauxval(AT_HWCAP);
41	    if ((hwcap & HWCAP_SVE) == 0) {
42	        log_skip(CpuNotSupportedSkipCategory,
43	                 "to be implemented (placeholder): ARM SVE required for insert_extract_sve");
44	        return EXIT_SKIP;
45	    }
46	#endif
47	    auto *data = new test_data_sve;
48	    std::mt19937 rng(std::random_device{}());
49	    (void)rng;
50	    memset(data->mem_buf, 0, sizeof(data->mem_buf));
51	    test->data = data;
52	    return EXIT_SUCCESS;
53	}
54	
55	#ifdef __aarch64__
56	static int insert_extract_sve_run(struct test *test, int cpu) {
57	    (void)cpu;
58	    auto *data = static_cast<test_data_sve *>(test->data);
59	    std::mt19937 rng(std::random_device{}());
60	    std::uniform_real_distribution<float> dist(-100.0f, 100.0f);
61	
62	    static std::atomic<uint64_t> iter{0};
63	
64	    do {
65	        // 1. 生成原始向量 (4 lane, 与原版一致)
66	        float orig_vals[IE_LANES];
67	        for (int i = 0; i < IE_LANES; ++i) orig_vals[i] = dist(rng);
68	        svbool_t pg = svwhilelt_b32((uint64_t)0, (uint64_t)IE_LANES);
69	        svfloat32_t orig_vec = svld1_f32(pg, orig_vals);
70	
71	        // 2. 随机选择 lane 和插入值
72	        int lane = (int)(rng() % IE_LANES);
73	        float insert_val = dist(rng);
74	
75	        // 3. SVE 插入: 单 lane 谓词选择 (svsel) —— vsetq_lane 的谓词等价
76	        uint32_t lane_sel[IE_LANES];
77	        for (int i = 0; i < IE_LANES; ++i) lane_sel[i] = (i == lane) ? 1u : 0u;
78	        svbool_t lane_p = svcmpne_n_u32(pg, svld1_u32(pg, lane_sel), 0);
79	        svfloat32_t ins_vec = svdup_f32(insert_val);
80	        svfloat32_t new_vec = svsel_f32(lane_p, ins_vec, orig_vec);
81	
82	        // SVE 提取: 谓词控读回该 lane (vgetq_lane 的等价读)
83	        float new_vals[IE_LANES];
84	        svst1_f32(pg, new_vals, new_vec);
85	        float extracted = new_vals[lane];
86	
87	        // 4. 验证插入/提取一致性
88	        bool insert_extract_ok = (extracted == insert_val);
89	
90	        // 5. Store/Load 一致性测试
91	        svst1_f32(pg, data->mem_buf, orig_vec);
92	        svfloat32_t loaded_vec = svld1_f32(pg, data->mem_buf);
93	        bool store_load_ok = (svcntp_b32(pg, svcmpeq_f32(pg, orig_vec, loaded_vec)) == IE_LANES);
94	
95	        bool passed = insert_extract_ok && store_load_ok;
96	
97	        uint64_t iteration = iter.fetch_add(1, std::memory_order_relaxed);
98	        const char *color = passed ? "\033[32m" : "\033[31m";
99	        const char *result_str = passed ? "PASS" : "FAIL";
100	
101	        fprintf(stderr, "insert_extract_sve: Iter %lu, lane=%d, insert_val=%.2f, extracted=%.2f, result=%s%s%s\n",
102	                iteration, lane, insert_val, extracted, color, result_str, "\033[0m");
103	        fflush(stderr);
104	
105	        if (!passed) {
106	            report_fail_msg("insert_extract_sve: insert/extract or store/load consistency failure");
107	            return EXIT_FAILURE;
108	        }
109	
110	    } while (test_time_condition(test));
111	
112	    return EXIT_SUCCESS;
113	}
114	#else
115	static int insert_extract_sve_run(struct test *test, int cpu) {
116	    (void)test; (void)cpu;
117	    return EXIT_SKIP;
118	}
