1	/**
2	 * @copyright
3	 * Copyright 2025 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b movbe_dump_probe_c_sve
7	 * @parblock
8	 * PROBE C (SVE): store-to-load-forwarding — each thread keeps a private copy of
9	 * the input, the swapped bytes are stored BACK to the private input position and
10	 * reloaded from there (vector SLF probe).
11	 * SVE port of movbe: byte-swap followed by another byte-swap restoring
12	 * the original order, on SVE vector lanes. Each 32-bit element's bytes
13	 * are permuted by svtbl with the [3,2,1,0] index table (bit-exact vs
14	 * __builtin_bswap32, 50k random vectors verified); the swapped value is
15	 * stored and reloaded through svst1/svld1 (the vector store->load path
16	 * that mirrors the scalar trigger recipe's reload). Input is random
17	 * (framework RNG at init), reused per iteration exactly as the original.
18	 * @endparblock
19	 */
20	
21	#include "sandstone.h"
22	#include <cstdint>
23	#include <cstring>
24	
25	#if defined(__aarch64__)
26	#include <arm_sve.h>
27	#include <sys/auxv.h>
28	
29	#ifndef HWCAP_SVE
30	#define HWCAP_SVE (1 << 22)
31	#endif
32	#endif
33	
34	#define MOVBE_BUFFER_SIZE (1 << 14)
35	
36	struct movbe_dump_probe_c_sve_data {
37	    uint32_t *input;
38	    uint32_t *swapped;
39	};
40	
41	static int movbe_dump_probe_c_sve_init(struct test *test)
42	{
43	#if defined(__aarch64__)
44	    unsigned long hwcap = getauxval(AT_HWCAP);
45	    if ((hwcap & HWCAP_SVE) == 0) {
46	        log_skip(CpuNotSupportedSkipCategory,
47	                 "to be implemented (placeholder): ARM SVE required for movbe_dump_probe_c_sve");
48	        return EXIT_SKIP;
49	    }
50	#endif
51	    auto *data = (movbe_dump_probe_c_sve_data *)malloc(sizeof(movbe_dump_probe_c_sve_data));
52	    data->input = (uint32_t *)aligned_alloc_safe(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
53	    data->swapped = (uint32_t *)aligned_alloc_safe(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
54	
55	    for (size_t i = 0; i < MOVBE_BUFFER_SIZE; ++i) {
56	        data->input[i] = random32();
57	    }
58	
59	    test->data = data;
60	    return EXIT_SUCCESS;
61	}
62	
63	#if defined(__aarch64__)
64	static int movbe_dump_probe_c_sve_run(struct test *test, int cpu)
65	{
66	    (void)cpu;
67	    auto *data = (movbe_dump_probe_c_sve_data *)test->data;
68	
69	    /* bswap32 的 svtbl 索引: 每元素 [3,2,1,0] */
70	    static const uint8_t idx4[4] = {3, 2, 1, 0};
71	
72	    const int lanes = svcntw();
73	    uint8_t vidx_bytes[64];
74	    for (int i = 0; i < lanes && i < 16; ++i)
75	        for (int b = 0; b < 4; ++b)
76	            vidx_bytes[i * 4 + b] = (uint8_t)(i * 4 + idx4[b]);
77	    svbool_t pg_batch = svwhilelt_b8((uint64_t)0, (uint64_t)(lanes < 16 ? lanes * 4 : 64));
78	    svuint8_t vidx = svld1_u8(pg_batch, vidx_bytes);
79	
80	    /* 每线程私有副本 (SLF 探针, 消除多写者竞争) */
81	    static thread_local uint32_t *priv_input = nullptr;
82	    if (!priv_input) priv_input = (uint32_t *)aligned_alloc(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
83	    memcpy(priv_input, data->input, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
84	
85	    TEST_LOOP(test, 1 << 13) {
86	        /* 每外层迭代重置私有副本 (store-back 污染下一遍; 原版标量逐 i 独立访问无此问题) */
87	        memcpy(priv_input, data->input, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
88	        for (size_t base = 0; base < MOVBE_BUFFER_SIZE; base += lanes) {
89	            int n = (MOVBE_BUFFER_SIZE - base < (size_t)lanes) ? (int)(MOVBE_BUFFER_SIZE - base) : lanes;
90	            svbool_t pg = svwhilelt_b8((uint64_t)0, (uint64_t)(n * 4));
91	
92	            /* 载入 n 个 32-bit 元素 (向量) → 字节级重排 */
93	            uint8_t in_bytes[64];
94	            memcpy(in_bytes, priv_input + base, n * 4);
95	            svuint8_t vswapped = svtbl_u8(svld1_u8(pg, in_bytes), vidx);
96	
97	            /* PROBE C: store-to-load-forwarding — 存回私有输入位置再读。
98	             * asm memory barrier 阻断编译器对 store/reload 序列的优化
99	             * (无屏障时编译器消除真实 reload, 破坏 SLF 语义)。 */
100	            memcpy(priv_input + base, in_bytes, n * 4);
101	            /* ★ 直接 store 到输入位置 (SLF 核心, svst1 直打堆无栈中转) */
102	            svst1_u8(pg, (uint8_t *)(priv_input + base), vswapped);
103	            __asm__ volatile("" ::: "memory");
104	            /* ★ reload: svld1 直接读刚写过的输入位置 (真实 store→load 转发) */
105	            svuint8_t reloaded = svld1_u8(pg, (const uint8_t *)(priv_input + base));
106	
107	            /* 再交换一次还原 (同一索引表, svtbl 可逆) */
108	            svuint8_t vrestored = svtbl_u8(reloaded, vidx);
109	            uint8_t out_bytes[64];
110	            svst1_u8(pg, out_bytes, vrestored);
111	
112	            /* 校验: 还原值 == 输入值; ONLY on failure: dump input/golden/actual/xor + 字节分解 */
113	            uint32_t restored[16];
114	            memcpy(restored, out_bytes, n * 4);
115	            for (int i = 0; i < n; ++i) {
116	                if (restored[i] != data->input[base + i]) {
117	                    uint32_t inputv = data->input[base + i];
118	                    uint32_t golden = inputv;
119	                    uint32_t actual = restored[i];
120	                    uint32_t xorv = golden ^ actual;
121	                    unsigned char *ib = (unsigned char *)&inputv;
122	                    unsigned char *gb = (unsigned char *)&golden;
123	                    unsigned char *ab = (unsigned char *)&actual;
124	                    unsigned char *xb = (unsigned char *)&xorv;
125	                    log_error("MovBE-SVE-dump: Round-trip failed at index %u: "
126	                              "input=0x%08X golden=0x%08X actual=0x%08X xor=0x%08X | "
127	                              "bytes[b3 b2 b1 b0] input=%02X%02X%02X%02X "
128	                              "golden=%02X%02X%02X%02X actual=%02X%02X%02X%02X "
129	                              "xor=%02X%02X%02X%02X",
130	                              (unsigned)(base + i), inputv, golden, actual, xorv,
131	                              ib[3], ib[2], ib[1], ib[0],
132	                              gb[3], gb[2], gb[1], gb[0],
133	                              ab[3], ab[2], ab[1], ab[0],
134	                              xb[3], xb[2], xb[1], xb[0]);
135	                    report_fail_msg("MovBE-SVE: Round-trip failed at index %u",
136	                                    (unsigned)(base + i));
137	                }
138	            }
139	        }
140	    }
141	
142	    return EXIT_SUCCESS;
143	}
144	#else
145	static int movbe_dump_probe_c_sve_run(struct test *test, int cpu)
146	{
147	    (void)test; (void)cpu;
148	    log_skip(CpuNotSupportedSkipCategory,
149	             "to be implemented (placeholder): ARM SVE required for movbe_dump_probe_c_sve");
150	    return EXIT_SKIP;
151	}
152	#endif
153	
154	static int movbe_dump_probe_c_sve_cleanup(struct test *test)
155	{
156	    auto *data = (movbe_dump_probe_c_sve_data *)test->data;
157	    if (data) {
158	        free(data->input);
159	        free(data->swapped);
160	        free(data);
161	    }
162	    return EXIT_SUCCESS;
163	}
164	
165	DECLARE_TEST(movbe_dump_probe_c_sve,
166	             "SVE byte-swap round-trip with dump-on-failure: svtbl [3,2,1,0] + vector "
167	             "store/reload, input/golden/actual/xor byte breakdown on failure (port of movbe_dump)")
168	    .test_init = movbe_dump_probe_c_sve_init,
169	    .test_run = movbe_dump_probe_c_sve_run,
170	    .test_cleanup = movbe_dump_probe_c_sve_cleanup,
171	    .quality_level = TEST_QUALITY_PROD,
172	END_DECLARE_TEST
173

