1	/**
2	 * @copyright
3	 * Copyright 2025 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b insert_extract_sve
7	 * @parblock
8	 * SVE port of insert_extract: random lane insert + extract round-trip on
9	 * an SVE vector. Insert = predicate-gated single-lane write (svsel with a
10	 * single-lane predicate); extract = svlastb on the shifted vector or a
11	 * predicate-gated read. Store/load consistency via svst1/svld1 + svcmpeq.
12	 * Values come from the per-thread framework RNG (reproducible via -s); the
13	 * store/load sub-check uses a function-local stack buffer (thread-private,
14	 * no shared state) with an asm memory barrier forcing a real reload. On
15	 * failure the full lane/value state is dumped via log_error before
16	 * report_fail_msg.
17	 * @endparblock
18	 */
19	
20	#include "sandstone.h"
21	#include <cstdint>
22	
23	#ifdef __aarch64__
24	#include <arm_sve.h>
25	#include <sys/auxv.h>
26	
27	#ifndef HWCAP_SVE
28	#define HWCAP_SVE (1 << 22)
29	#endif
30	#endif
31	
32	#define IE_LANES 4
33	
34	static int insert_extract_sve_init(struct test *test) {
35	    (void)test;
36	#ifdef __aarch64__
37	    unsigned long hwcap = getauxval(AT_HWCAP);
38	    if ((hwcap & HWCAP_SVE) == 0) {
39	        log_skip(CpuNotSupportedSkipCategory,
40	                 "to be implemented (placeholder): ARM SVE required for insert_extract_sve");
41	        return EXIT_SKIP;
42	    }
43	#endif
44	    return EXIT_SUCCESS;
45	}
46	
47	#ifdef __aarch64__
48	static int insert_extract_sve_run(struct test *test, int cpu) {
49	    (void)cpu;
50	
51	    do {
52	        // 1. 生成原始向量 (4 lane, 与原版一致) — 框架每线程 RNG, 种子可复现
53	        float orig_vals[IE_LANES];
54	        for (int i = 0; i < IE_LANES; ++i)
55	            orig_vals[i] = frandomf_scale(200.0f) - 100.0f;
56	        svbool_t pg = svwhilelt_b32((uint64_t)0, (uint64_t)IE_LANES);
57	        svfloat32_t orig_vec = svld1_f32(pg, orig_vals);
58	
59	        // 2. 随机选择 lane 和插入值
60	        int lane = (int)(random32() % IE_LANES);
61	        float insert_val = frandomf_scale(200.0f) - 100.0f;
62	
63	        // 3. SVE 插入: 单 lane 谓词选择 (svsel) —— vsetq_lane 的谓词等价
64	        uint32_t lane_sel[IE_LANES];
65	        for (int i = 0; i < IE_LANES; ++i) lane_sel[i] = (i == lane) ? 1u : 0u;
66	        svbool_t lane_p = svcmpne_n_u32(pg, svld1_u32(pg, lane_sel), 0);
67	        svfloat32_t ins_vec = svdup_f32(insert_val);
68	        svfloat32_t new_vec = svsel_f32(lane_p, ins_vec, orig_vec);
69	
70	        // SVE 提取: 谓词控读回该 lane (vgetq_lane 的等价读)
71	        float new_vals[IE_LANES];
72	        svst1_f32(pg, new_vals, new_vec);
73	        float extracted = new_vals[lane];
74	
75	        // 4. 验证插入/提取一致性
76	        bool insert_extract_ok = (extracted == insert_val);
77	
78	        // 5. Store/Load 一致性测试 — 函数局部栈缓冲, 线程私有, 消除多写者竞态;
79	        //    asm 内存屏障阻断编译器消除真实 reload (先例 movbe_dump_probe_c_sve)
80	        float sl_buf[IE_LANES];
81	        svst1_f32(pg, sl_buf, orig_vec);
82	        __asm__ volatile("" ::: "memory");
83	        svfloat32_t loaded_vec = svld1_f32(pg, sl_buf);
84	        bool store_load_ok = (svcntp_b32(pg, svcmpeq_f32(pg, orig_vec, loaded_vec)) == IE_LANES);
85	
86	        // 失败时 dump 全量现场 (两类子检查分别标注), report_fail_msg 为 noreturn
87	        if (!insert_extract_ok || !store_load_ok) {
88	            log_error("insert_extract_sve: sub-check failure: insert/extract=%s store/load=%s | "
89	                      "lane=%d insert_val=%.6g extracted=%.6g | "
90	                      "orig_vals=[%g %g %g %g] new_vals=[%g %g %g %g] sl_buf=[%g %g %g %g]",
91	                      insert_extract_ok ? "ok" : "FAIL", store_load_ok ? "ok" : "FAIL",
92	                      lane, insert_val, extracted,
93	                      orig_vals[0], orig_vals[1], orig_vals[2], orig_vals[3],
94	                      new_vals[0], new_vals[1], new_vals[2], new_vals[3],
95	                      sl_buf[0], sl_buf[1], sl_buf[2], sl_buf[3]);
96	            report_fail_msg("insert_extract_sve: insert/extract or store/load consistency failure");
97	        }
98	
99	    } while (test_time_condition(test));
100	
101	    return EXIT_SUCCESS;
102	}
103	#else
104	static int insert_extract_sve_run(struct test *test, int cpu) {
105	    (void)test; (void)cpu;
106	    log_skip(CpuNotSupportedSkipCategory,
107	             "to be implemented (placeholder): ARM SVE required for insert_extract_sve");
108	    return EXIT_SKIP;
109	}
110	#endif
111	
112	DECLARE_TEST(insert_extract_sve, "SVE lane insert/extract round-trip via predicate-gated select (port of insert_extract)")
113	    .groups = DECLARE_TEST_GROUPS(&group_math),
114	    .test_init = insert_extract_sve_init,
115	    .test_run = insert_extract_sve_run,
116	    .quality_level = TEST_QUALITY_PROD,
117	END_DECLARE_TEST
118
